// Simula busca de dados da API RH
return {
  colaboradores: [
    { full_name: 'João Silva', document_id: '123.456.789-00', email: 'joao@yazaki.com', department: 'Operações', position: 'Gerente', hire_date: '2020-01-15', status: 'ATIVO' },
    { full_name: 'Maria Santos', document_id: '234.567.890-11', email: 'maria@yazaki.com', department: 'Financeiro', position: 'Analista', hire_date: '2021-03-20', status: 'ATIVO' },
    { full_name: 'Pedro Costa', document_id: '345.678.901-22', email: 'pedro@yazaki.com', department: 'TI', position: 'Desenvolvedor', hire_date: '2022-06-10', status: 'ATIVO' }
  ]
};

const externos = $node["Buscar Dados RH"].output.first().json.colaboradores;

const transformados = externos.map(c => ({
  nome: c.full_name,
  cpf: c.document_id,
  email: c.email,
  departamento: c.department,
  cargo: c.position,
  data_admissao: c.hire_date,
  ativo: c.status === 'ATIVO'
}));

return { colaboradores: transformados, total: transformados.length };

const dados = $node["Transformar Dados"].output.first().json;

return {
  novos_colaboradores: dados.total,
  timestamp: new Date().toISOString(),
  mensagem: `${dados.total} colaborador(es) sincronizado(s) com sucesso`
};
